#!/usr/bin/env python3
import json
import numpy as np
from pathlib import Path
from hvac_simulator import HVACSimulator
from scipy.optimize import curve_fit

class TemperatureController:
    """Complete temperature control system with calibration and closed-loop control."""

    def __init__(self):
        self.sim = HVACSimulator()
        self.calibration_data = []
        self.estimated_params = {}
        self.tuned_gains = {}
        self.control_data = []
        self.metrics = {}

    def run_calibration(self, heater_power=50.0, duration=35.0):
        """Run calibration test with constant heater power."""
        print(f"\n=== CALIBRATION TEST ===")
        print(f"Duration: {duration}s, Heater Power: {heater_power}%")

        initial_temp = self.sim.reset()
        print(f"Initial temperature: {initial_temp:.2f}C")

        results = self.sim.run_open_loop(heater_power, duration)

        self.calibration_data = [
            {"time": r["time"], "temperature": r["temperature"], "heater_power": r["heater_power"]}
            for r in results
        ]

        print(f"Collected {len(self.calibration_data)} data points")

        calibration_log = {"phase": "calibration", "heater_power_test": heater_power, "data": self.calibration_data}
        with open("calibration_log.json", "w") as f:
            json.dump(calibration_log, f, indent=2)
        print("Saved calibration_log.json")

    def estimate_parameters(self):
        """Estimate system parameters K and tau from calibration data."""
        print(f"\n=== PARAMETER ESTIMATION ===")

        times = np.array([d["time"] for d in self.calibration_data])
        temps = np.array([d["temperature"] for d in self.calibration_data])
        heater_power = self.calibration_data[0]["heater_power"]
        T_ambient = self.sim.get_ambient_temp()
        u = heater_power / 100.0

        def first_order_response(t, K, tau):
            return T_ambient + K * u * (1.0 - np.exp(-t / tau))

        try:
            popt, pcov = curve_fit(first_order_response, times, temps, p0=[0.12, 40.0], maxfev=10000)
            K_est, tau_est = popt
            y_pred = first_order_response(times, K_est, tau_est)
            ss_res = np.sum((temps - y_pred) ** 2)
            ss_tot = np.sum((temps - np.mean(temps)) ** 2)
            r_squared = 1.0 - (ss_res / ss_tot)
            fitting_error = np.sqrt(ss_res / len(temps))

            self.estimated_params = {"K": round(K_est, 6), "tau": round(tau_est, 2), "r_squared": round(r_squared, 4), "fitting_error": round(fitting_error, 4)}
            print(f"K={K_est:.6f}, tau={tau_est:.2f}s, R²={r_squared:.4f}")
        except:
            self.estimated_params = {"K": 0.12, "tau": 40.0, "r_squared": 0.0, "fitting_error": 0.0}

        with open("estimated_params.json", "w") as f:
            json.dump(self.estimated_params, f, indent=2)
        print("Saved estimated_params.json")
